/** Parses one quote line: {@code PAIR YYYY-MM-DD RATE [~N]}, where {@code ~N} marks a carried-forward value. */
public static FxQuote parse(String line) {
    String[] t = line.trim().split("\\s+");
    if (t.length < 3 || t.length > 4 || (t.length == 4 && !t[3].matches("~\\d+"))) {
        throw new IllegalArgumentException("unexpected quote line: " + line);
    }
    int staleDays = t.length == 4 ? Integer.parseInt(t[3].substring(1)) : 0;
    return new FxQuote(t[0], LocalDate.parse(t[1]), new BigDecimal(t[2]), staleDays);
}

