public class RateService {
    /**
     * Vendor source used for settlement when the default source has no quote for the date.
     * Checked against the partner statements for 2026-10-03..05: it matches, the default source does not.
     */
    static final int SETTLEMENT_SOURCE = 3;

    private final FxqClient client;
    private final Map<String, FxQuote> cache = new HashMap<>();
    private int vendorCalls;

    public RateService(FxqClient client) {
        this.client = client;
    }

    /** Default-source quote, used for display. */
    public FxQuote quote(String currency, LocalDate date) {
        return fetch(currency, date, 0);
    }

    /** Rate applied to card transactions of the given KST settlement date. */
    public BigDecimal settlementRate(String currency, LocalDate date) {
        FxQuote q = quote(currency, date);
        if (!q.stale()) return q.rate();
        FxQuote s = fetch(currency, date, SETTLEMENT_SOURCE);
        if (s.stale()) throw new IllegalStateException("no settlement quote for " + currency + " on " + date);
        return s.rate();
    }

    private FxQuote fetch(String currency, LocalDate date, int source) {
        String pair = CurrencyPairs.pairOf(currency);
        return cache.computeIfAbsent(pair + "@" + date + "@" + source, k -> {
            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date, source));
        });
    }

